import {cellType,cellParts,selectedPart}from './cell-anatomy.js?v=20261023-physicscomplete01';
let serial=0;
export function detailedCellFigure({type='animal',highlight='',labelled=false}={}){
 type=cellType(type);highlight=selectedPart(type,highlight);const id='cellDiagram'+(++serial),plant=type==='plant',bacterium=type==='bacterium';const stroke=key=>highlight===key?' stroke="#f58b79" stroke-width="5"':' stroke="#e4ece8" stroke-opacity=".65" stroke-width="1.5"';const selected=key=>highlight===key?'#f58b79':'';
 const title=labelled?({animal:'Animal cell',plant:'Plant cell',bacterium:'Bacterial cell'}[type]):'Schematic cell specimen';
 let body=plant?'<rect x="49" y="31" width="322" height="268" rx="24" fill="#d0c6ad"'+stroke('wall')+'/><rect x="60" y="42" width="300" height="246" rx="18" fill="url(#'+id+'gel)"'+stroke('membrane')+'/>':bacterium?'<rect x="38" y="89" width="344" height="153" rx="76" fill="#a9c0bd"'+stroke('wall')+'/><rect x="48" y="99" width="324" height="133" rx="66" fill="url(#'+id+'gel)"'+stroke('membrane')+'/>':'<path d="M66 75 C125 25 269 33 331 94 C380 147 351 243 282 273 C197 311 75 269 49 199 C33 153 36 107 66 75Z" fill="url(#'+id+'gel)"'+stroke('membrane')+'/>';
 if(plant)body+='<rect x="155" y="77" width="168" height="174" rx="37" fill="#a5c8d6" fill-opacity=".83"'+stroke('vacuole')+'/>';
 if(!bacterium){const x=plant?104:164,y=plant?163:153;body+='<ellipse cx="'+x+'" cy="'+y+'" rx="'+(plant?30:41)+'" ry="'+(plant?36:44)+'" fill="url(#'+id+'nucleus)"'+stroke('nucleus')+'/><circle cx="'+(x-7)+'" cy="'+(y-8)+'" r="12" fill="#e7b8a9" opacity=".65"/>';const positions=plant?[[107,234,-25],[296,267,10]]:[[105,226,22],[280,103,-18],[279,238,8]];for(const[x,y,angle]of positions)body+='<g transform="translate('+x+' '+y+') rotate('+angle+')"><path d="M-25 -3 C-24 -18 -9 -16 0 -11 C15 -4 23 -13 27 -1 C30 14 13 18 0 12 C-12 6 -25 14 -25 -3Z" fill="#deb88d"'+stroke('mitochondria')+'/><path d="M-17 -6 l5 13 5 -11 7 14 6 -12 7 9 5 -8" fill="none" stroke="#8d6d66" stroke-width="2.2"/></g>';}
 if(plant)for(const[x,y,angle]of [[107,77,-20],[337,121,85],[104,272,5]])body+='<g transform="translate('+x+' '+y+') rotate('+angle+')"><ellipse rx="27" ry="14" fill="#729c8e"'+stroke('chloroplasts')+'/>'+[-14,-5,5,14].map(x=>'<path d="M'+x+' -7 v14" stroke="#c6ddbf" stroke-width="4"/>').join('')+'</g>';
 if(bacterium)body+='<path d="M115 155 C113 118 159 127 170 157 C182 190 217 202 236 176 C258 146 213 123 197 149 C178 179 141 201 122 178 C106 159 107 148 115 155Z" fill="none" stroke="'+(selected('dna')||'#e3baa4')+'" stroke-width="'+(highlight==='dna'?6:4)+'"/><ellipse cx="307" cy="187" rx="18" ry="12" fill="none" stroke="'+(selected('plasmid')||'#e3baa4')+'" stroke-width="'+(highlight==='plasmid'?5:3)+'"/>';
 const dots=plant?[[80,120],[133,112],[130,205],[333,208],[180,267]]:bacterium?[[83,150],[145,213],[275,123],[263,202],[329,138]]:[[116,91],[233,87],[306,172],[226,249],[89,171],[222,211]];
 for(const[x,y]of dots)body+='<g fill="'+(selected('ribosomes')||'#1e3f57')+'"><circle cx="'+x+'" cy="'+y+'" r="'+(highlight==='ribosomes'?5:3.5)+'"/><circle cx="'+(x+5)+'" cy="'+(y+3)+'" r="'+(highlight==='ribosomes'?3:2.2)+'"/></g>';
 if(highlight==='cytoplasm')body+='<circle cx="'+(plant?132:bacterium?273:275)+'" cy="'+(plant?56:bacterium?165:188)+'" r="10" fill="none" stroke="#f58b79" stroke-width="4"/>';
 const label=highlight?cellParts[highlight].name:labelled?title:'';
 return '<svg class="bio-cell-art" viewBox="0 0 420 340" role="img" aria-label="'+title+(highlight?' · '+cellParts[highlight].name+' highlighted':'')+'"><title>'+title+'</title><desc>Clear schematic cutaway; selected structures use a thick outline as well as colour. Relative sizes and colours are symbolic; small structures shown may not be visible with a school light microscope.</desc><defs><radialGradient id="'+id+'gel" cx="30%" cy="25%"><stop stop-color="#bdcfca"/><stop offset="1" stop-color="#688fa0"/></radialGradient><radialGradient id="'+id+'nucleus" cx="30%" cy="25%"><stop stop-color="#eabca8"/><stop offset="1" stop-color="#ac7583"/></radialGradient></defs>'+body+(label?'<text x="210" y="327" text-anchor="middle" fill="#e4ece8" font-size="15">'+label+'</text>':'')+'</svg>';
}
